using Amazon.SQS;
using Amazon.SQS.Model;

public class SqsFifoDedup
{
    private readonly IAmazonSQS _sqs;
    private readonly string _queueUrl;

    public SqsFifoDedup(IAmazonSQS sqs, string queueUrl)
    {
        _sqs = sqs;
        _queueUrl = queueUrl;
    }

    public async Task SendAsync(string groupId, string body)
    {
        // Content-based dedup enabled on queue; no deduplicationId needed
        await _sqs.SendMessageAsync(new SendMessageRequest
        {
            QueueUrl = _queueUrl,
            MessageBody = body,
            MessageGroupId = groupId
        });
    }
}

// Queue setup via AWS CLI:
// aws sqs create-queue \
//   --queue-name orders.fifo \
//   --attributes FifoQueue=true,ContentBasedDeduplication=true

const { BloomFilter } = require('bloom-filters');
const redis = require('ioredis');

// In-memory Bloom filter with ~1% false positive rate
const filter = new BloomFilter(100000, 0.01);
const redisKey = 'msg:dedup:seen';

async function isDuplicate(messageId) {
  if (filter.has(messageId)) {
    // Double-check Redis to avoid false-positive discards
    const exists = await redis.sismember(redisKey, messageId);
    return exists;
  }

  const added = await redis.sadd(redisKey, messageId);
  if (added) {
    await redis.expire(redisKey, 3600);
    filter.add(messageId);
    return false;
  }

  return true;
}

// Usage in consumer
if (await isDuplicate(msg.messageId)) {
  await channel.ack(msg);
  return; // skip duplicate
}
